import re

from django.utils import timezone


def reprendre_candidatures(apps, schema_editor):
    """Ancien booléen « traité » -> statut « En revue » ; calcul du pré-score existant."""
    Candidature = apps.get_model('carrieres', 'Candidature')
    for c in Candidature.objects.select_related('offre'):
        if c.traite:
            c.statut = 'en_revue'
            c.traite = False
        cv = (c.cv.name or '').lower() if c.cv else ''
        longueur = len((c.message or '').strip())
        chiffres = re.sub(r'\D', '', c.telephone or '')
        reference = timezone.localdate(c.created_at)
        score = (20 if cv.endswith('.pdf') else 10 if cv else 0)
        score += 25 if c.lettre_motivation else 0
        score += 25 if longueur >= 300 else 15 if longueur >= 120 else 5 if longueur else 0
        score += 10 if len(chiffres) >= 10 else 0
        score += 20 if not c.offre.date_limite or reference <= c.offre.date_limite else 0
        c.score_auto = min(100, score)
        c.save(update_fields=['statut', 'traite', 'score_auto'])



